BEGIN;
CREATE TABLE provider_node_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash bytea NOT NULL UNIQUE,expires_at timestamptz NOT NULL,uses_remaining integer NOT NULL CHECK(uses_remaining BETWEEN 0 AND 10),created_by uuid NOT NULL REFERENCES provider_users(user_id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(expires_at>created_at));
CREATE TABLE provider_nodes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invitation_id uuid NOT NULL REFERENCES provider_node_invitations(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 160),audience text NOT NULL DEFAULT 'node' CHECK(audience='node'),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','revoked')),public_key_pem text NOT NULL,key_fingerprint text NOT NULL UNIQUE,claim_token_hash bytea NOT NULL UNIQUE,proof_verified_at timestamptz,approved_at timestamptz,approved_by uuid REFERENCES provider_users(user_id),claimed_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE node_challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),node_id uuid NOT NULL REFERENCES provider_nodes(id) ON DELETE CASCADE,purpose text NOT NULL CHECK(purpose IN('enrollment','authentication')),nonce_hash bytea NOT NULL UNIQUE,expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE node_credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),node_id uuid NOT NULL REFERENCES provider_nodes(id) ON DELETE CASCADE,serial text NOT NULL UNIQUE,certificate_pem text NOT NULL,not_before timestamptz NOT NULL,not_after timestamptz NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','rotated','revoked')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE node_sessions(token_hash bytea PRIMARY KEY,node_id uuid NOT NULL REFERENCES provider_nodes(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE node_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),target_node_id uuid NOT NULL REFERENCES provider_nodes(id),type text NOT NULL CHECK(type='node.runtime_info.v1'),status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','ready','succeeded','failed','expired')),idempotency_key text NOT NULL UNIQUE CHECK(length(idempotency_key) BETWEEN 8 AND 128),expires_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES provider_users(user_id),created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE node_operation_outbox(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,operation_id uuid NOT NULL UNIQUE REFERENCES node_operations(id),attempts integer NOT NULL DEFAULT 0,lease_owner text,lease_until timestamptz,delivered_at timestamptz,available_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE node_operation_results(operation_id uuid PRIMARY KEY REFERENCES node_operations(id),node_id uuid NOT NULL REFERENCES provider_nodes(id),result jsonb NOT NULL,observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE node_heartbeats(node_id uuid PRIMARY KEY REFERENCES provider_nodes(id),observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),agent_version text NOT NULL);
CREATE TABLE control_security_state(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),epoch bigint NOT NULL DEFAULT 1,quarantined boolean NOT NULL DEFAULT false,checkpoint_epoch bigint,updated_at timestamptz NOT NULL DEFAULT now());INSERT INTO control_security_state DEFAULT VALUES;
CREATE TABLE security_reconciliation_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,checkpoint_epoch bigint NOT NULL,resource_type text NOT NULL,resource_id text NOT NULL,event text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(checkpoint_epoch,resource_type,resource_id,event));

ALTER TABLE provider_node_invitations ENABLE ROW LEVEL SECURITY;ALTER TABLE provider_node_invitations FORCE ROW LEVEL SECURITY;ALTER TABLE provider_nodes ENABLE ROW LEVEL SECURITY;ALTER TABLE provider_nodes FORCE ROW LEVEL SECURITY;ALTER TABLE node_challenges ENABLE ROW LEVEL SECURITY;ALTER TABLE node_challenges FORCE ROW LEVEL SECURITY;ALTER TABLE node_credentials ENABLE ROW LEVEL SECURITY;ALTER TABLE node_credentials FORCE ROW LEVEL SECURITY;ALTER TABLE node_sessions ENABLE ROW LEVEL SECURITY;ALTER TABLE node_sessions FORCE ROW LEVEL SECURITY;ALTER TABLE node_operations ENABLE ROW LEVEL SECURITY;ALTER TABLE node_operations FORCE ROW LEVEL SECURITY;ALTER TABLE node_operation_outbox ENABLE ROW LEVEL SECURITY;ALTER TABLE node_operation_outbox FORCE ROW LEVEL SECURITY;ALTER TABLE node_operation_results ENABLE ROW LEVEL SECURITY;ALTER TABLE node_operation_results FORCE ROW LEVEL SECURITY;ALTER TABLE node_heartbeats ENABLE ROW LEVEL SECURITY;ALTER TABLE node_heartbeats FORCE ROW LEVEL SECURITY;
CREATE POLICY node_inv_scope ON provider_node_invitations USING(current_setting('app.provider_role',true)='owner' OR encode(token_hash,'hex')=current_setting('app.node_invitation_hash',true));
CREATE POLICY node_scope ON provider_nodes USING(current_setting('app.provider_role',true) IN('owner','operator','auditor') OR id::text=current_setting('app.node_id',true) OR invitation_id IN(SELECT id FROM provider_node_invitations WHERE encode(token_hash,'hex')=current_setting('app.node_invitation_hash',true)));
CREATE POLICY node_ch_scope ON node_challenges USING(node_id::text=current_setting('app.node_id',true));CREATE POLICY node_cred_scope ON node_credentials USING(current_setting('app.provider_role',true)='owner' OR node_id::text=current_setting('app.node_id',true));CREATE POLICY node_session_scope ON node_sessions USING(current_setting('app.provider_role',true)='owner' OR node_id::text=current_setting('app.node_id',true) OR encode(token_hash,'hex')=current_setting('app.node_session_hash',true));
CREATE POLICY node_ops_scope ON node_operations USING(current_setting('app.provider_role',true) IN('owner','operator','auditor') OR target_node_id::text=current_setting('app.node_id',true) OR current_setting('app.worker_role',true)='operation_dispatch');CREATE POLICY node_outbox_scope ON node_operation_outbox USING(current_setting('app.provider_role',true)='owner' OR current_setting('app.worker_role',true)='operation_dispatch' OR operation_id IN(SELECT id FROM node_operations));CREATE POLICY node_results_scope ON node_operation_results USING(current_setting('app.provider_role',true) IN('owner','operator','auditor') OR node_id::text=current_setting('app.node_id',true));CREATE POLICY node_beats_scope ON node_heartbeats USING(current_setting('app.provider_role',true) IN('owner','operator','auditor') OR node_id::text=current_setting('app.node_id',true));
COMMIT;
